<script setup lang="ts">
import { ref, onMounted, shallowRef } from 'vue'
import { getCapabilities, type Capabilities } from '@/services/capabilities'
import PageHeading from '@/components/PageHeading.vue'
import AppIcon from '@/components/AppIcon.vue'
import NoticeBox from '@/components/NoticeBox.vue'
const info = shallowRef<Capabilities>(), loading = ref(false), failure = ref('')
async function check(): Promise<void> { loading.value = true; failure.value = ''; try { info.value = await getCapabilities() } catch { failure.value = 'Device checks could not complete. No camera permission was requested.' } finally { loading.value = false } }
onMounted(check)
</script>
<template><div class="container narrow"><PageHeading back="/settings" eyebrow="KNOW WHAT YOUR PHONE CAN DO" title="The right tools for your space." subtitle="These checks inspect capabilities, not the make or price of your phone."><button class="btn btn-outline-primary" :disabled="loading" @click="check"><AppIcon name="reset" :size="18"/>Check again</button></PageHeading><p v-if="loading" class="loading-state">Checking this device…</p><NoticeBox v-if="failure" kind="error">{{ failure }}</NoticeBox><div v-if="info" class="card detail-card"><div class="device-hero"><AppIcon name="phone" :size="45"/><div><h2>{{ info.platform === 'web' ? 'Browser workspace' : `${info.platform === 'ios' ? 'iOS' : 'Android'} native workspace` }}</h2><p>No camera was opened by these checks.</p></div></div><div v-for="item in [{ name:'Secure context', supported:info.secure, text:'HTTPS or an approved native/local origin is required for camera and XR.' }, { name:'Browser camera API', supported:info.camera, text:'Camera access does not, by itself, provide 3D depth or tracking.' }, { name:'WebGL 2 viewer', supported:info.webgl, text:'Interactive 3D rendering; photos and file exports remain useful without it.' }, { name:'Immersive WebXR AR', supported:info.xr, text:'This is not proof of CPU depth support. A depth-enabled session must still succeed.' }, { name:'Native scanner bridge', supported:!!info.native, text:info.native?.reason || 'Open an installed native build to access ARKit or ARCore.' }]" :key="item.name" class="capability-row"><span class="capability-symbol" :class="{ yes:item.supported }"><AppIcon :name="item.supported ? 'check' : 'info'"/></span><div><strong>{{ item.name }}</strong><p>{{ item.text }}</p></div><span>{{ item.supported ? 'Available' : 'Not available' }}</span></div><NoticeBox v-if="info.nativeError" kind="warning">{{ info.nativeError }}</NoticeBox></div><section class="card detail-card"><h2>Supported capture paths</h2><div class="device-path"><h3>iPhone / iPad native build</h3><p>ARKit mesh reconstruction requires a device for which Apple’s scene-reconstruction support check succeeds, typically a LiDAR-equipped Pro device. The browser does not automatically gain native ARKit access.</p></div><div class="device-path"><h3>Android native build</h3><p>ARCore Depth is required. Some supported phones estimate depth from the moving camera without a dedicated depth sensor. ARCore installation, permission and depth support are checked at capture time.</p></div><div class="device-path"><h3>Browser / installed PWA</h3><p>Live scanning requires an immersive AR session with CPU-accessible depth and DOM-overlay support. An installed PWA does not grant native LiDAR access. Unsupported browsers still support organizing, importing, editing, viewing and exporting local projects.</p></div><NoticeBox kind="warning">Simulator builds and automated browser tests cannot qualify physical room scanning. A real-device acceptance run is required before relying on a capture’s accuracy.</NoticeBox></section><RouterLink to="/new" class="btn btn-primary w-100">Create a space<AppIcon name="arrow"/></RouterLink></div></template>
